/*
 * prog59_rule110 – reproduces the behavior of the supplied binary.
 *
 * The program expects exactly two command‑line arguments:
 *
 *   1. A string consisting only of the characters ‘0’ and ‘1’.
 *      Its length must be between 1 and 60 inclusive.
 *   2. A non‑negative integer giving the number of steps to simulate.
 *      The value is capped at 200.
 *
 * If any of the above conditions are violated the program prints
 *
 *      INVALID_INPUT
 *
 * (followed by a newline) and exits.
 *
 * Otherwise it prints the evolution of the elementary cellular automaton
 * "Rule 110".  The first line is the initial pattern, each subsequent line
 * is the next generation, for a total of <steps> lines.  The automaton is
 * computed with fixed‑zero boundary conditions (cells outside the pattern
 * are considered ‘0’).
 *
 * The implementation follows the logic discovered in the decompiled
 * state‑machine of the original binary, but is written in clear, idiomatic
 * C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN   60          /* maximum allowed pattern length            */
#define MAX_STEPS 200         /* maximum number of generations to display  */

/* Rule 110 lookup table.
 * Index = (left << 2) | (center << 1) | right   (left,center,right are 0/1)
 * Value = new state (0 or 1)
 *
 * Binary representation of rule 110 is 01101110 (from pattern 111 to 000):
 *   111 → 0
 *   110 → 1
 *   101 → 1
 *   100 → 0
 *   011 → 1
 *   010 → 1
 *   001 → 1
 *   000 → 0
 */
static const unsigned char RULE110[8] = {
    0, 1, 1, 1, 0, 1, 1, 0   /* ordered as 000,001,010,011,100,101,110,111 */
};

/* Helper: print the pattern stored in buf (not null‑terminated) */
static void print_row(const unsigned char *buf, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        putchar('0' + buf[i]);
    putchar('\n');
}

/* Validate that a string consists only of ‘0’ and ‘1’. */
static int is_binary_string(const char *s)
{
    for (; *s; ++s)
        if (*s != '0' && *s != '1')
            return 0;
    return 1;
}

/* Compute the next generation of Rule 110. */
static void next_row(const unsigned char *cur, unsigned char *next, size_t len)
{
    for (size_t i = 0; i < len; ++i) {
        unsigned left  = (i == 0)     ? 0 : cur[i - 1];
        unsigned center = cur[i];
        unsigned right = (i + 1 == len) ? 0 : cur[i + 1];

        unsigned idx = (left << 2) | (center << 1) | right;
        next[i] = RULE110[idx];
    }
}

int main(int argc, char *argv[])
{
    /* ----- argument count check ----- */
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ----- first argument: initial pattern ----- */
    const char *init_str = argv[1];
    size_t len = strlen(init_str);

    if (len == 0 || len > MAX_LEN || !is_binary_string(init_str)) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ----- second argument: number of steps ----- */
    char *endptr;
    long steps = strtol(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0' || steps < 0) {
        puts("INVALID_INPUT");
        return 0;
    }
    if (steps > MAX_STEPS)
        steps = MAX_STEPS;

    /* ----- buffers for current and next rows ----- */
    unsigned char cur[MAX_LEN];
    unsigned char nxt[MAX_LEN];

    for (size_t i = 0; i < len; ++i)
        cur[i] = (unsigned char)(init_str[i] - '0');

    /* ----- main simulation loop ----- */
    for (long step = 0; step < steps; ++step) {
        print_row(cur, len);
        next_row(cur, nxt, len);
        memcpy(cur, nxt, len);
    }

    return 0;
}
